args.TargetContent:
{/* Top Lists Panel: Crew Members Grid */}
<div className="p-4 bg-black/30 border-b border-white/10 select-none">
  {/* Crew Members Section */}
  <div className="border border-white/5 bg-black/20 rounded-xl p-4 flex flex-col min-w-0">
    <div className="flex items-center justify-between pb-2.5 border-b border-white/5 mb-3">
      <div className="flex items-center gap-2">
        <span className="text-xs">👥</span>
        <span className="text-xs font-bold text-white/70 uppercase tracking-wider">Crew Members</span>
      </div>
      <span className="text-[10px] font-bold text-white/20 bg-white/5 px-2 py-0.5 rounded">{crewMembers.filter(m => m.id !== 'openshifts').length}</span>
    </div>

    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 xl:grid-cols-8 gap-2 max-h-[180px] overflow-y-auto custom-scrollbar pr-1">
      {/* All Crew reset option */}
      <button
        type="button"
        onClick={() => setScheduleCrewFilter('')}
        className={`w-full text-left px-3 py-2 rounded-lg flex items-center gap-2.5 border-none cursor-pointer transition-all ${
          !scheduleCrewFilter ? 'bg-white/5 text-white/80' : 'bg-transparent text-white/40 hover:bg-white/[0.03]'
        }`}
      >
        <div className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-[9px] font-bold text-white/60 shrink-0">∀</div>
        <span className="text-xs font-bold">All Crew</span>
      </button>

      {crewMembers.filter(m => m.id !== 'openshifts').map(member => {
        const weekHrs = getCrewScheduledHours(member.id, next7Days);
        const monthHrs = getCrewScheduledHoursForMonth(member.id, currentWeekStart);
        const isActive = scheduleCrewFilter === member.id;

        return (
          <button
            key={member.id}
            type="button"
            onClick={() => setScheduleCrewFilter(isActive ? '' : member.id)}
            className={`w-full text-left px-3 py-2 rounded-lg flex items-center gap-2.5 border-none cursor-pointer transition-all group ${
              isActive 
                ? 'bg-amber-500/10' 
                : 'bg-transparent hover:bg-white/[0.03]'
            }`}
          >
            {(() => {
              const hasImage = member.avatar && (member.avatar.startsWith('http') || member.avatar.startsWith('/'));
              if (hasImage) {
                return <img src={member.avatar} alt="" className="w-6 h-6 rounded-full object-cover shrink-0" />;
              }
              const initials = member.initials || member.name.split(' ').map((n: string) => n[0]).join('').toUpperCase().slice(0, 2);
              const color = member.color || getAvatarColor(member.name);
              return (
                <div className="w-6 h-6 rounded-full flex items-center justify-center font-bold text-[8px] text-white shrink-0" style={{ backgroundColor: color }}>
                  {initials}
                </div>
              );
            })()}

            <div className="flex-1 min-w-0">
              <p className={`text-xs font-bold truncate ${isActive ? 'text-white' : 'text-white/70'}`}>{member.name}</p>
              <div className="flex items-center gap-2 mt-0.5">
                <span className="text-[9px] font-bold text-white/30 uppercase">{member.role}</span>
                <span className="text-[9px] font-black text-amber-400/50">W:{weekHrs.toFixed(1)}h</span>
                <span className="text-[9px] font-black text-blue-400/40">M:{monthHrs.toFixed(1)}h</span>
              </div>
            </div>
          </button>
        );
      })}
    </div>
  </div>
</div>

{/* Grid Body */}
<div className="p-4 bg-black/10 min-w-0">
